export interface ProPlayerInfo {
  name: string;
  team: string;
  role?: string;
  highlightMatch?: string;
}

export interface SkinReviewDetails {
  soundDesign: string;
  recoilFeel: string;
  reloadInspect: string;
  finisher: string;
  pros: string[];
  cons: string[];
  verdict: string;
  placeboEffect: string;
}

export interface StoreFrequencyInfo {
  tier: "Cực Hiếm (< 1%)" | "Hiếm (1% - 2%)" | "Bình Thường (2% - 5%)" | "Đặc Biệt Giới Hạn (0%)";
  rotationWeight: number;
  poolStatus: "Daily Shop 4 Ô Hàng Ngày" | "Chợ Đen & Shop Hàng Ngày" | "Vaulted (Giới Hạn Không Bán Lại)";
  avgWaitDays: string;
  nightMarketEligible: boolean;
  nightMarketStatus: string;
  priceVP: number;
}

export interface CommunityScore {
  overall: number;
  audioScore: number;
  animationScore: number;
  finisherScore: number;
  totalVotes: number;
}

export interface WeaponSkin {
  id: string;
  name: string;
  weapon: string;
  bundle: string;
  tier: "Premium" | "Exclusive" | "Ultra" | "Select" | "Deluxe";
  tierLabel: string;
  tierColor: "purple" | "orange" | "amber" | "blue" | "green";
  releaseDate: string;
  pickRate: string;
  proUsers: ProPlayerInfo[];
  image: string;
  rating: number; // 0 to 10
  priceVP: number;
  reviewDetails: SkinReviewDetails;
  storeFrequency: StoreFrequencyInfo;
  communityScore: CommunityScore;
  variants: string[];
}

